class ReverbProcessor extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name:'size',    defaultValue:0.5,  minValue:0,   maxValue:1 },
      { name:'decay',   defaultValue:2.5,  minValue:0.1, maxValue:10 },
      { name:'damping', defaultValue:0.5,  minValue:0,   maxValue:1 },
      { name:'predelay',defaultValue:20,   minValue:0,   maxValue:150 },
      { name:'wet',     defaultValue:0.25, minValue:0,   maxValue:1 },
      { name:'width',   defaultValue:0.8,  minValue:0,   maxValue:1 },
      { name:'bypass',  defaultValue:0,    minValue:0,   maxValue:1 },
    ];
  }
  constructor() {
    super();
    this._sr = sampleRate;
    const sz = Math.ceil(this._sr * 0.05);
    // 8 Schroeder allpass + 4 comb filters (FDN)
    const delays = [1557,1617,1491,1422,1277,1356,1188,1116,225,341,441,556].map(d=>Math.ceil(d*this._sr/44100));
    this._combs = delays.slice(0,8).map(d=>({ buf:new Float32Array(d), pos:0, fb:0 }));
    this._aps   = delays.slice(8).map(d=>({ buf:new Float32Array(d), pos:0 }));
    this._pdBuf = new Float32Array(Math.ceil(this._sr*0.2));
    this._pdPos = 0;
    this._lp = 0;
    this._lastDecay = -1; this._lastDamp = -1;
  }
  _rebuildFB(decay, damp) {
    this._combs.forEach((c,i) => { c.fb = Math.pow(10, -3*c.buf.length/(this._sr*decay)); });
    this._damping = damp;
    this._lastDecay=decay; this._lastDamp=damp;
  }
  process(inputs, outputs, params) {
    const inp=inputs[0], out=outputs[0]; if(!inp||!inp[0]) return true;
    const bypass=params.bypass[0]>0.5;
    const wet=params.wet[0], decay=params.decay[0], damp=params.damping[0];
    const pdSamples=Math.floor(params.predelay[0]*this._sr/1000);
    if(decay!==this._lastDecay||damp!==this._lastDamp) this._rebuildFB(decay,damp);
    if(bypass){for(let c=0;c<inp.length;c++){const ic=inp[c],oc=out[c];for(let i=0;i<ic.length;i++)oc[i]=ic[i];}return true;}
    const ic=inp[0];
    for(let i=0;i<ic.length;i++){
      // pre-delay
      this._pdBuf[this._pdPos]=ic[i];
      const delayed=this._pdBuf[(this._pdPos-pdSamples+this._pdBuf.length)%this._pdBuf.length];
      this._pdPos=(this._pdPos+1)%this._pdBuf.length;
      // combs
      let sum=0;
      for(const c of this._combs){
        const r=c.buf[c.pos];
        this._lp=r*(1-damp)+this._lp*damp;
        const w=delayed+this._lp*c.fb;
        c.buf[c.pos]=w; c.pos=(c.pos+1)%c.buf.length;
        sum+=r;
      }
      sum/=this._combs.length;
      // allpass
      for(const a of this._aps){
        const r=a.buf[a.pos];
        a.buf[a.pos]=sum+0.5*r; a.pos=(a.pos+1)%a.buf.length;
        sum=r-0.5*sum;
      }
      for(let c=0;c<out.length;c++){
        const dry=inp[c]?inp[c][i]:ic[i];
        out[c][i]=dry*(1-wet)+sum*wet*(c===1?params.width[0]:1);
      }
    }
    return true;
  }
}
registerProcessor('reverb', ReverbProcessor);
