class NoiseGateProcessor extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name:'threshold', defaultValue:-40, minValue:-80, maxValue:0 },
      { name:'attack',    defaultValue:1,   minValue:0.1, maxValue:50 },
      { name:'hold',      defaultValue:50,  minValue:0,   maxValue:500 },
      { name:'release',   defaultValue:100, minValue:10,  maxValue:1000 },
      { name:'range',     defaultValue:-60, minValue:-80, maxValue:0 },
      { name:'bypass',    defaultValue:0,   minValue:0,   maxValue:1 },
    ];
  }
  constructor() { super(); this._sr=sampleRate; this._env=0; this._holdCnt=0; this._open=false; }
  process(inputs, outputs, params) {
    const inp=inputs[0], out=outputs[0]; if(!inp||!inp[0]) return true;
    const bypass=params.bypass[0]>0.5;
    const thr=Math.pow(10,params.threshold[0]/20);
    const att=Math.exp(-1/(this._sr*params.attack[0]/1000));
    const rel=Math.exp(-1/(this._sr*params.release[0]/1000));
    const hold=Math.floor(params.hold[0]*this._sr/1000);
    const range=Math.pow(10,params.range[0]/20);
    for(let c=0;c<inp.length;c++){
      const ic=inp[c],oc=out[c];
      for(let i=0;i<ic.length;i++){
        if(bypass){oc[i]=ic[i];continue;}
        const level=Math.abs(ic[i]);
        if(level>thr){ this._open=true; this._holdCnt=hold; }
        else if(this._holdCnt>0){ this._holdCnt--; }
        else { this._open=false; }
        const target=this._open ? 1 : range;
        if(target>this._env) this._env=att*this._env+(1-att)*target;
        else this._env=rel*this._env+(1-rel)*target;
        oc[i]=ic[i]*this._env;
      }
    }
    return true;
  }
}
