class WidenerProcessor extends AudioWorkletProcessor {
  static get parameterDescriptors() {
    return [
      { name:'width',   defaultValue:0.5, minValue:0, maxValue:1 },
      { name:'monoLow', defaultValue:1,   minValue:0, maxValue:1 },
      { name:'bypass',  defaultValue:0,   minValue:0, maxValue:1 },
    ];
  }
  process(inputs, outputs, params) {
    const inp=inputs[0], out=outputs[0]; if(!inp||inp.length<2) return true;
    const bypass=params.bypass[0]>0.5;
    const width=params.width[0], monoLow=params.monoLow[0];
    const L=inp[0], R=inp[1], oL=out[0], oR=out[1];
    for(let i=0;i<L.length;i++){
      if(bypass){oL[i]=L[i];oR[i]=R[i];continue;}
      const mid=(L[i]+R[i])*0.5, side=(L[i]-R[i])*0.5*(1+width*1.5);
      oL[i]=mid+side; oR[i]=mid-side;
    }
    return true;
  }
}
